Define a set of marker keywords representing common failure indicators, and check
each line idx_e301f289 of the log against those markers, recording a hit wherever a marker is found:
static class LogTools
{
[Description("Extract the most relevant failure signals from a CI log
for troubleshooting and classification.")]
public static string ExtractFailureSignals(
[Description("Raw CI log content.")] string logContent,
[Description("Maximum number of lines to return.")] int maxLines =
30)
{
if (string.IsNullOrWhiteSpace(logContent)) return "No log content
provided.";
var lines = logContent.Split('\n',
StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
// Keep it deterministic: focus on common failure markers.
var markers = new[]
{
"ERROR", "FAIL", "FATAL", "Unhandled exception", "Build
FAILED", "Test Run Failed", "Exited with code", "MSB1", "NETSDK", "NU1"
};
var hits = lines
.Where(l => markers.Any(m => l.Contains(m,
StringComparison.OrdinalIgnoreCase)))
.Take(maxLines)
.ToList();
if (hits.Count == 0)
{
hits = lines.TakeLast(Math.Min(maxLines,
lines.Length)).ToList();
}
return "=== Failure Signals ===\n" + string.Join('\n', hits);
}
}

